def reverse(s):
    result = ""
    for ch in s:
        result = ch + result
    return result

def capitalise(word):
    word[0] = word[0].upper()
    return word

def count_vowels(s):
    count = 0
    for ch in s.lower():
        if ch in "aeiou":
            count += 1
    return count

def even_and_positive(n):
    if n <= 0:
        return False
    return n % 2 == 0

def grade(score):
