def squares(nums):
    result = []
    for x in nums:
        result = result.append(x * x)
    return result

def total(nums):
    for x in nums:
        s = 0
        s += x
    return s

def smallest(nums):
    best = nums[0]
    for x in nums[1:]:
        if x < best:
            best = x
    return best

def largest(nums):
    best = 0
    for x in nums:
        if x > best:
            best = x
    return best

def find(lst, target):
    i = 0
    while i < len(lst) and lst[i] != target:
        i += 1
    if i == len(lst):
        return -1
    return i

def inside_count(grid, r, c):
    count = 0
    moves = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for dr, dc in moves:
        nr, nc = r + dr, c + dc
        if (0 <= nr < len(grid)
                and 0 <= nc < len(grid[0])):
            count += 1
    return count

def grid_sum(grid):
    total = 0
    for r in range(len(grid)):
        for c in range(len(grid)):
            total += grid[r][c]
    return total

def absolute(n):
    if n < 0:
        return -n
    return n

def add_one(nums):
    for i in range(len(nums)):
        nums[i] += 1

def is_pal(s):
    if len(s) < 2:
        return True
    if s[0] != s[-1]:
        return False
    return is_pal(s[1:-1])

def power(base, exp):
    if exp == 0:
        return 1
    base * power(base, exp - 1)

def total(lst):
    if not lst:
        return 0
    return lst[-1] + total(lst[:-1])

def count_down(n):
    if n == 0:
