def escape(maze, r, c):
    if r < 0 or r >= len(maze):
        return False
    if c < 0 or c >= len(maze[0]):
        return False
    if maze[r][c] == "#":
        return False
    if maze[r][c] == "E":
        return True
    return (escape(maze, r + 1, c)
            or escape(maze, r - 1, c)
            or escape(maze, r, c + 1)
            or escape(maze, r, c - 1))

MOVES = [(1, 0), (-1, 0), (0, 1), (0, -1)]

def escape(maze, r, c, seen):
    if not 0 <= r < len(maze):
        return False
    if not 0 <= c < len(maze[r]):
        return False
    if maze[r][c] == "#" or (r, c) in seen:
        return False
    if maze[r][c] == "E":
        return True
    seen.add((r, c))
    for dr, dc in MOVES:
        if escape(maze, r + dr, c + dc, seen):
            return True
    return False

def escape(maze, r, c, seen):
    if maze[r][c] == "#" or (r, c) in seen:
        return False
    if r < 0 or r >= len(maze):
        return False
    if c < 0 or c >= len(maze[0]):
        return False
    if maze[r][c] == "E":
        return True
    seen.add((r, c))
    return (escape(maze, r + 1, c, seen)
            or escape(maze, r - 1, c, seen)
            or escape(maze, r, c + 1, seen)
            or escape(maze, r, c - 1, seen))

def escape(maze, r, c):
    if not (0 <= r < len(maze)
            and 0 <= c < len(maze[0])):
        return False
    if maze[r][c] == "E":
        return True
    if maze[r][c] != ".":
        return False
    maze[r][c] = "v"
    return (escape(maze, r + 1, c)
            or escape(maze, r - 1, c)
            or escape(maze, r, c + 1)
            or escape(maze, r, c - 1))

def paths(rows, cols):
    if rows == 1 or cols == 1:
        return 1
    down = paths(rows - 1, cols)
    right = paths(rows, cols - 1)
    return down + right

def choose(n, k):
    if k == 0 or k == n:
        return 1
    return choose(n - 1, k - 1) + choose(n - 1, k)

def binary(n, path):
    if len(path) == n:
        print("".join(path))
        return
    for bit in "01":
        path.append(bit)
        binary(n, path)

def perms(items, path, result):
    if len(path) == len(items):
        result.append(path[:])
        return
    for x in items:
        if x not in path:
            path.append(x)
            perms(items, path, result)
            path.pop()
